#!/usr/bin/env python3
"""Compare generated bytes without requiring a git checkout."""
from pathlib import Path
import subprocess
root=Path(__file__).resolve().parent.parent
paths=[*sorted((root/'backend/internal/store/sqlc').glob('*.go')),root/'frontend/src/api/schema.d.ts']
before={str(p.relative_to(root)):p.read_bytes() for p in paths}
subprocess.run(['make','generate'],cwd=root,check=True)
paths=[*sorted((root/'backend/internal/store/sqlc').glob('*.go')),root/'frontend/src/api/schema.d.ts']
after={str(p.relative_to(root)):p.read_bytes() for p in paths}
if before!=after:raise SystemExit('Generated files changed. Review and rerun make check.')
print('Generated files are byte-identical.')
